        }
        if (this.isModelDead()) {
            if (this.isVehicle()) {
                this.ejectPassengers();
            }

            this.setHovering(false);
            this.setFlying(false);
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
        if (animationTick > this.getAnimation().getDuration() && !level.isClientSide) {
            animationTick = 0;
        }
    }

